import sys
from itertools import combinations

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    k = int(input[1])
    cards = []
    for i in range(n):
        p = int(input[3 * i + 2])
        c = int(input[3 * i + 3])
        l = int(input[3 * i + 4])
        cards.append((p, c, l))

    min_level = -1
    for level in range(1, n + 1):
        valid_cards = [card for card in cards if card[2] <= level]
        for r in range(1, len(valid_cards) + 1):
            for combo in combinations(valid_cards, r):
                total_power = sum(card[0] for card in combo)
                total_magic = sum(card[1] for card in combo)
                if total_power >= k:
                    valid = True
                    for i in range(r):
                        for j in range(i + 1, r):
                            if is_prime(combo[i][1] + combo[j][1]):
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        min_level = level
                        break
            if min_level != -1:
                break
        if min_level != -1:
            break

    print(min_level)

if __name__ == "__main__":
    main()
